package com.example.order;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import java.util.Map;@SpringBootApplication @RestController public class OrderServiceApplication {private final RestClient client=RestClient.create("http://localhost:8081");public static void main(String[] a){SpringApplication.run(OrderServiceApplication.class,a);}@GetMapping("/orders/{productId}") public Map<String,Object> order(@PathVariable int productId){Map product=client.get().uri("/products/{id}",productId).retrieve().body(Map.class);return Map.of("orderStatus","PLACED","product",product);}}
